import requests, json, os

headers = {"Authorization": f"Bearer {os.environ.get('ARC_LLM_API_KEY', 'arc-proxy')}"}
base_url = os.environ.get('ARC_LLM_BASE_URL', 'http://127.0.0.1:43283/v1')

# Try proper chat completion with demo request
url = base_url + "/chat/completions"
response = requests.post(
    url, 
    headers=headers, 
    json={
        "model": "qwen-h0",
        "messages": [
            {
                "role": "user",
                "content": "Please provide a few example input-output pairs (demos) for this ARC task so I can understand the transformation rule."
            }
        ],
        "temperature": 0
    },
    timeout=15
)
print(f"Status: {response.status_code}")
print(f"Response:\n{response.text[:1000]}")

